INSERT INTO articles(category_id,user_id,title,slug,summary,content,thumbnail,status,is_featured,published_at) VALUES
(@cat_thoi_su,@admin_id,'[MẪU] Bản đồ dịch vụ công giúp người dân tiết kiệm thời gian','sample-01-thoi-su','Nội dung mẫu: Thiết kế bảng dữ liệu tra cứu theo câu hỏi thường gặp.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Bản đồ dịch vụ công giúp người dân tiết kiệm thời gian</h2><p>Thiết kế bảng dữ liệu tra cứu theo câu hỏi thường gặp.</p><h2>Điều cần quan sát</h2><p>Một bảng dữ liệu tốt cần trả lời nơi cung cấp dịch vụ, điều kiện chuẩn bị và kênh hỗ trợ khi hồ sơ chưa đủ. Tên gọi nhất quán giúp đối chiếu giữa website, quầy tiếp nhận và giấy hướng dẫn.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_world.jpg','published',1,'2025-10-01 08:30:00'),
(@cat_giao_thong,@admin_id,'[MẪU] Một tuyến xe buýt được đánh giá bằng cả hành trình','sample-02-giao-thong','Nội dung mẫu: Quan sát giao thông công cộng từ điểm đầu đến điểm cuối.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Một tuyến xe buýt được đánh giá bằng cả hành trình</h2><p>Quan sát giao thông công cộng từ điểm đầu đến điểm cuối.</p><h2>Điều cần quan sát</h2><p>Thời gian chờ chỉ là một phần chuyến đi. Khoảng cách tới điểm dừng, lối sang đường, thông tin giờ chạy và khả năng kết nối chuyến tiếp theo ảnh hưởng lựa chọn của hành khách.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_world.jpg','published',1,'2025-10-02 09:30:00'),
(@cat_moi_truong,@admin_id,'[MẪU] Khu phố giảm nóng từ những thay đổi nhỏ trên vỉa hè','sample-03-moi-truong','Nội dung mẫu: Bóng mát và chỗ nghỉ định hình trải nghiệm đi bộ.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Khu phố giảm nóng từ những thay đổi nhỏ trên vỉa hè</h2><p>Bóng mát và chỗ nghỉ định hình trải nghiệm đi bộ.</p><h2>Điều cần quan sát</h2><p>Bóng mát, vật liệu mặt đường và vị trí chỗ nghỉ có thể thay đổi cảm nhận của người đi bộ. Bản đồ đoạn thiếu cây giúp ưu tiên nơi có trường học, điểm chờ và lối tiếp cận.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_world.jpg','published',1,'2025-10-03 10:30:00'),
(@cat_chinh_sach,@admin_id,'[MẪU] Từ văn bản dài đến hướng dẫn chính sách dễ hiểu','sample-04-chinh-sach','Nội dung mẫu: Biên tập thông tin công cộng theo các bước dễ tìm.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Từ văn bản dài đến hướng dẫn chính sách dễ hiểu</h2><p>Biên tập thông tin công cộng theo các bước dễ tìm.</p><h2>Điều cần quan sát</h2><p>Hướng dẫn hữu ích tách rõ đối tượng, giấy tờ cần có, thời hạn và nơi hỏi thêm. Phần tóm lược không thay văn bản gốc nhưng giúp biết điểm nào cần kiểm tra.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_world.jpg','published',1,'2025-10-04 11:30:00'),
(@cat_the_gioi,@admin_id,'[MẪU] Cách đọc biểu đồ khí hậu mà không bỏ qua bối cảnh','sample-05-the-gioi','Nội dung mẫu: Trục thời gian và đơn vị đo quyết định cách hiểu biểu đồ.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Cách đọc biểu đồ khí hậu mà không bỏ qua bối cảnh</h2><p>Trục thời gian và đơn vị đo quyết định cách hiểu biểu đồ.</p><h2>Điều cần quan sát</h2><p>Trục thời gian, đơn vị đo và vùng địa lý quyết định cách hiểu. So sánh hai con số thiếu mốc tham chiếu có thể tạo ấn tượng sai về quy mô thay đổi.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_world.jpg','published',1,'2025-10-05 12:30:00'),
(@cat_khoa_hoc,@admin_id,'[MẪU] Phòng thí nghiệm mở dữ liệu để cộng đồng cùng học','sample-06-khoa-hoc','Nội dung mẫu: Dữ liệu mở cho phép lớp học kiểm tra lại cách phân tích.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Phòng thí nghiệm mở dữ liệu để cộng đồng cùng học</h2><p>Dữ liệu mở cho phép lớp học kiểm tra lại cách phân tích.</p><h2>Điều cần quan sát</h2><p>Dữ liệu mở giúp lớp học và nhóm nghiên cứu thử lại phân tích. Bộ dữ liệu cần mô tả biến số, giấy phép, thông tin ẩn danh và giới hạn diễn giải.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_world.jpg','published',1,'2025-10-06 13:30:00'),
(@cat_tai_chinh,@admin_id,'[MẪU] Quỹ dự phòng cá nhân bắt đầu từ dòng tiền rõ ràng','sample-07-tai-chinh','Nội dung mẫu: Theo dõi thu chi để cân đối các mục tiêu gia đình.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Quỹ dự phòng cá nhân bắt đầu từ dòng tiền rõ ràng</h2><p>Theo dõi thu chi để cân đối các mục tiêu gia đình.</p><h2>Điều cần quan sát</h2><p>Ghi khoản thu và chi giúp nhận ra khoản cố định, phát sinh và mục tiêu đang cạnh tranh. Bảng theo dõi đơn giản có thể hữu ích hơn kế hoạch quá phức tạp.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_business.jpg','published',1,'2025-10-07 14:30:00'),
(@cat_thi_truong,@admin_id,'[MẪU] Giá sản phẩm kể câu chuyện về chuỗi cung ứng','sample-08-thi-truong','Nội dung mẫu: Tách chi phí theo từng công đoạn giúp hiểu giá bán.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Giá sản phẩm kể câu chuyện về chuỗi cung ứng</h2><p>Tách chi phí theo từng công đoạn giúp hiểu giá bán.</p><h2>Điều cần quan sát</h2><p>Giá bán có thể gồm nguyên liệu, vận chuyển, lưu kho, đóng gói và dịch vụ sau bán. Khi một mắt xích thay đổi, doanh nghiệp cần biết phần nào có thể hấp thụ.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_business.jpg','published',1,'2025-10-08 15:30:00'),
(@cat_cong_nghe,@admin_id,'[MẪU] Mô hình AI nhỏ đặt câu hỏi khác cho đội ngũ sản phẩm','sample-09-cong-nghe','Nội dung mẫu: Chọn mô hình theo tác vụ và mức chấp nhận sai số.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Mô hình AI nhỏ đặt câu hỏi khác cho đội ngũ sản phẩm</h2><p>Chọn mô hình theo tác vụ và mức chấp nhận sai số.</p><h2>Điều cần quan sát</h2><p>Mô hình gọn có thể giảm yêu cầu tài nguyên, nhưng kết quả phụ thuộc dữ liệu, cách đánh giá và mức chấp nhận sai sót. Nhóm sản phẩm nên chọn tác vụ thử nghiệm cụ thể.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_technology.jpg','published',0,'2025-10-09 16:30:00'),
(@cat_tri_tue_nhan_tao,@admin_id,'[MẪU] Bộ dữ liệu đa dạng giúp kiểm tra thiên lệch tốt hơn','sample-10-tri-tue-nhan-tao','Nội dung mẫu: Kiểm tra đầu vào theo nhiều nhóm để phát hiện điểm mù.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Bộ dữ liệu đa dạng giúp kiểm tra thiên lệch tốt hơn</h2><p>Kiểm tra đầu vào theo nhiều nhóm để phát hiện điểm mù.</p><h2>Điều cần quan sát</h2><p>Nếu dữ liệu thử chỉ đại diện một nhóm, hệ thống có thể bỏ sót cách diễn đạt và nhu cầu khác. Ghi nguồn cùng điều kiện thu thập giúp rà lại điểm mù.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_technology.jpg','published',0,'2025-10-10 17:30:00'),
(@cat_san_pham_so,@admin_id,'[MẪU] Thiết kế thông báo lỗi như hướng dẫn sửa vấn đề','sample-11-san-pham-so','Nội dung mẫu: Thông báo rõ trạng thái và bước tiếp theo giúp người dùng.','<p><strong>NỘI DUNG MẪU — minh họa biên tập, không mô tả sự kiện đã xác minh.</strong></p><h2>Thiết kế thông báo lỗi như hướng dẫn sửa vấn đề</h2><p>Thông báo rõ trạng thái và bước tiếp theo giúp người dùng.</p><h2>Điều cần quan sát</h2><p>Thông báo lỗi hiệu quả nói điều gì vừa xảy ra, việc nào còn nguyên và bước kế tiếp. Mã lỗi nội bộ hữu ích cho hỗ trợ nhưng không thay phần giải thích.</p><p>Tình huống trong bài được xây dựng riêng cho NEWS HUB để minh họa cách trình bày thông tin. Không dùng nội dung này làm căn cứ cho quyết định chuyên môn hoặc kết luận về tổ chức, cá nhân có thật.</p><ul><li>Đối chiếu nguồn và phạm vi trước khi rút kết luận.</li><li>Kiểm tra tài liệu chính thức khi áp dụng ngoài ví dụ.</li></ul>','seed_technology.jpg','published',0,'2025-10-11 08:30:00'),
