-- Idempotent sample content for NEWS HUB. All articles below are explicitly illustrative, not verified news.
USE `news_hub`;
START TRANSACTION;
SET @role_admin=(SELECT id FROM roles WHERE name='admin'); SET @role_user=(SELECT id FROM roles WHERE name='user');
ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),password_hash=VALUES(password_hash),status='active';
SET @admin_id=(SELECT id FROM users WHERE email='admin@newshub.local'); SET @reader_id=(SELECT id FROM users WHERE email='reader@newshub.local');
ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),sort_order=VALUES(sort_order),status='active';
SET @cat_thoi_su=(SELECT id FROM categories WHERE slug='thoi-su');
SET @cat_the_gioi=(SELECT id FROM categories WHERE slug='the-gioi');
SET @cat_kinh_doanh=(SELECT id FROM categories WHERE slug='kinh-doanh');
SET @cat_cong_nghe=(SELECT id FROM categories WHERE slug='cong-nghe');
SET @cat_the_thao=(SELECT id FROM categories WHERE slug='the-thao');
SET @cat_giai_tri=(SELECT id FROM categories WHERE slug='giai-tri');
SET @cat_giao_duc=(SELECT id FROM categories WHERE slug='giao-duc');
SET @cat_suc_khoe=(SELECT id FROM categories WHERE slug='suc-khoe');
SET @cat_phap_luat=(SELECT id FROM categories WHERE slug='phap-luat');
SET @cat_doi_song=(SELECT id FROM categories WHERE slug='doi-song');
ON DUPLICATE KEY UPDATE parent_id=VALUES(parent_id),name=VALUES(name),description=VALUES(description),sort_order=VALUES(sort_order),status='active';
SET @cat_chinh_sach=(SELECT id FROM categories WHERE slug='chinh-sach');
SET @cat_giao_thong=(SELECT id FROM categories WHERE slug='giao-thong');
SET @cat_moi_truong=(SELECT id FROM categories WHERE slug='moi-truong');
SET @cat_khoa_hoc=(SELECT id FROM categories WHERE slug='khoa-hoc');
SET @cat_tai_chinh=(SELECT id FROM categories WHERE slug='tai-chinh');
SET @cat_thi_truong=(SELECT id FROM categories WHERE slug='thi-truong');
SET @cat_tri_tue_nhan_tao=(SELECT id FROM categories WHERE slug='tri-tue-nhan-tao');
SET @cat_san_pham_so=(SELECT id FROM categories WHERE slug='san-pham-so');
SET @cat_bong_da=(SELECT id FROM categories WHERE slug='bong-da');
SET @cat_dien_anh=(SELECT id FROM categories WHERE slug='dien-anh');
SET @cat_dai_hoc=(SELECT id FROM categories WHERE slug='dai-hoc');
SET @cat_dinh_duong=(SELECT id FROM categories WHERE slug='dinh-duong');
SET @cat_y_te_so=(SELECT id FROM categories WHERE slug='y-te-so');
SET @cat_phap_luat_so=(SELECT id FROM categories WHERE slug='phap-luat-so');
SET @cat_van_hoa=(SELECT id FROM categories WHERE slug='van-hoa');
SET @cat_do_thi=(SELECT id FROM categories WHERE slug='do-thi');
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),user_id=VALUES(user_id),title=VALUES(title),summary=VALUES(summary),content=VALUES(content),thumbnail=VALUES(thumbnail),status=VALUES(status),is_featured=VALUES(is_featured),published_at=VALUES(published_at);
SELECT a.id,'seed_technology.jpg','Ảnh minh họa của bài viết mẫu.','Minh họa biên tập technology',0 FROM articles a WHERE a.slug='sample-09-cong-nghe' AND NOT EXISTS (SELECT 1 FROM article_images ai WHERE ai.article_id=a.id AND ai.image_path='seed_technology.jpg')
UNION ALL
SELECT a.id,'seed_sports.jpg','Ảnh minh họa của bài viết mẫu.','Minh họa biên tập sports',0 FROM articles a WHERE a.slug='sample-13-the-thao' AND NOT EXISTS (SELECT 1 FROM article_images ai WHERE ai.article_id=a.id AND ai.image_path='seed_sports.jpg')
UNION ALL
SELECT a.id,'seed_lifestyle.jpg','Ảnh minh họa của bài viết mẫu.','Minh họa biên tập lifestyle',0 FROM articles a WHERE a.slug='sample-17-giai-tri' AND NOT EXISTS (SELECT 1 FROM article_images ai WHERE ai.article_id=a.id AND ai.image_path='seed_lifestyle.jpg')
UNION ALL
SELECT a.id,'seed_education.jpg','Ảnh minh họa của bài viết mẫu.','Minh họa biên tập education',0 FROM articles a WHERE a.slug='sample-21-giao-duc' AND NOT EXISTS (SELECT 1 FROM article_images ai WHERE ai.article_id=a.id AND ai.image_path='seed_education.jpg')
UNION ALL
SELECT a.id,'seed_lifestyle.jpg','Ảnh minh họa của bài viết mẫu.','Minh họa biên tập lifestyle',0 FROM articles a WHERE a.slug='sample-25-suc-khoe' AND NOT EXISTS (SELECT 1 FROM article_images ai WHERE ai.article_id=a.id AND ai.image_path='seed_lifestyle.jpg')
UNION ALL
SELECT a.id,'seed_lifestyle.jpg','Ảnh minh họa của bài viết mẫu.','Minh họa biên tập lifestyle',0 FROM articles a WHERE a.slug='sample-33-doi-song' AND NOT EXISTS (SELECT 1 FROM article_images ai WHERE ai.article_id=a.id AND ai.image_path='seed_lifestyle.jpg');
SELECT a.id,@reader_id,'SAMPLE: approved comment illustrating readable layout.','approved' FROM articles a WHERE a.slug='sample-01-thoi-su' AND NOT EXISTS (SELECT 1 FROM comments c WHERE c.article_id=a.id AND c.user_id=@reader_id AND c.content='SAMPLE: approved comment illustrating readable layout.')
UNION ALL SELECT a.id,@reader_id,'SAMPLE: pending comment waiting for moderation.','pending' FROM articles a WHERE a.slug='sample-02-giao-thong' AND NOT EXISTS (SELECT 1 FROM comments c WHERE c.article_id=a.id AND c.user_id=@reader_id AND c.content='SAMPLE: pending comment waiting for moderation.')
UNION ALL SELECT a.id,@reader_id,'SAMPLE: hidden comment for moderation checks.','hidden' FROM articles a WHERE a.slug='sample-03-moi-truong' AND NOT EXISTS (SELECT 1 FROM comments c WHERE c.article_id=a.id AND c.user_id=@reader_id AND c.content='SAMPLE: hidden comment for moderation checks.')
UNION ALL SELECT a.id,@reader_id,'SAMPLE: second approved editorial response.','approved' FROM articles a WHERE a.slug='sample-09-cong-nghe' AND NOT EXISTS (SELECT 1 FROM comments c WHERE c.article_id=a.id AND c.user_id=@reader_id AND c.content='SAMPLE: second approved editorial response.');COMMIT;